        private void LoadYearList()
        {
            SIM_GraduationResult obj = new SIM_GraduationResult();
            DataTable dtbYear = obj.GetDataTable("SIM_Year_Search");
            WebGlobal.InitDropDownList(ddlYearID, dtbYear, SIM_Year.C_YEARID, SIM_Year.C_YEARNAME, "--Chọn--");
            ddlYearID.SelectedValue = WebGlobal.ValueForDropBoxList(SYS_SettingService.GetStringValue("CurrentYearID"));
        }

        private void LoadExamDateList()
        {
            int? intYearID = WebGlobal.ToInt32(ddlYearID.SelectedValue);

            SIM_GraduationResult obj = new SIM_GraduationResult();
            DataTable dtbExamDate = obj.GetDataTable("SIM_ExamDate_SearchForGraduationCBX", "@YearID", intYearID);

            WebGlobal.InitDropDownList(ddlExamDateID, dtbExamDate, "ExamDateID", "ExamDateName", "--Chọn--");
        }

        private string GetSignDocSerial()
        {
            if (this.TemplateCode == "5" && this.ExamDateID.HasValue)
                return this.ExamDateID.Value.ToString();
            return uClass.ClassID;
        }

        private void BindDataGrid()
        {
            if (dtbData == null)
                return;

            if (dtbData.Rows.Count == 0)
            {
                if (!chkThanLy.Checked)
                    this.TemplateCode = "1";
                pnlEmpty.Visible = true;
                rptList.Visible = false;
            }
            else
            {
                if (!chkThanLy.Checked)
                {
                    int intOfficeId = Convert.ToInt32(dtbData.Rows[0]["OfficeID"]);
                    string strSpecialBranchId = dtbData.Rows[0]["SpecialBranchID"].ToString();
                    if ((intOfficeId == 10 || intOfficeId == 11) && strSpecialBranchId == "A")
                        this.TemplateCode = "2";
                    else if (intOfficeId == 10 || intOfficeId == 11)
                        this.TemplateCode = "3";
                    else if (strSpecialBranchId == "BCK" || strSpecialBranchId == "C1")
                        this.TemplateCode = "4";
                    else
                        this.TemplateCode = "1";

                    if (Request.Url.DnsSafeHost == "localhost" && Request["templatecode"] != null)
                        this.TemplateCode = Request["templatecode"].ToString();
                }

                pnlEmpty.Visible = false;
                rptList.Visible = true;
                rptList.DataSource = dtbData;
                rptList.DataBind();
            }

            BindTemplateNote();
            LoadSignCA_StudentContract();
            udpContent.Update();
        }

