        private void LoadData()
        {
            bool? bolDinhChi = null;
            if (rdoStatus1.Checked)
                bolDinhChi = false;
            else if (rdoStatus2.Checked)
                bolDinhChi = true;

            SimsObject.SIM_Student obj = new SimsObject.SIM_Student();
            this.dtbData = obj.GetDataTable("WEB_StudentInfoList_HD",
                                        "@ClassID", uClass.ClassID,
                                        "@CourseID", uClass.CourseID,
                                        "@ScienceID", uClass.ScienceID,
                                        "@DinhChi", bolDinhChi);

            if (dtbData != null)
            {
                if (dtbData.Rows.Count == 0)
                {
                    this.TemplateCode = "1";
                    pnlEmpty.Visible = true;
                    rptList.Visible = false;
                }
                else
                {
                    int intOfficeId = Convert.ToInt32(dtbData.Rows[0]["OfficeID"]);
                    string strSpecialBranchId = dtbData.Rows[0]["SpecialBranchID"].ToString();
                    if ((intOfficeId == 10 || intOfficeId == 11) && strSpecialBranchId == "A")
                        this.TemplateCode = "2";
                    else if (intOfficeId == 10 || intOfficeId == 11)
                        this.TemplateCode = "3";
                    else if (strSpecialBranchId == "BCK" || strSpecialBranchId == "C1")
                    {
                        if (chkThanLy.Checked)
                            this.TemplateCode = "5";
                        else
                            this.TemplateCode = "4";
                    }
                    else
                        this.TemplateCode = "1";

                    // debug local tự gõ mã mẫu trên trình duyệt để test mẫu cho nhanh
                    if (Request.Url.DnsSafeHost == "localhost" && Request["templatecode"] != null)
                        this.TemplateCode = Request["templatecode"].ToString();

                    pnlEmpty.Visible = false;
                    rptList.Visible = true;
                    rptList.DataSource = dtbData;
                    rptList.DataBind();
                }

                BindTemplateNote();
                LoadSignCA_StudentContract();
                udpContent.Update();
            }
            else
                MsgBox.ShowError("Việc tải thông tin bị lỗi!");
        }

        private bool IsValidData(bool isShowMsg = true)
        {
            if (uClass.ClassID == null)
            {
                if (isShowMsg)
                    MsgBox.ShowWarning("Bạn phải chọn lớp học!");

                return false;
            }

            return true;
        }

