        private void LoadDataMau5ThanhLy()
        {
            int? intExamDateID = WebGlobal.ValueFromDropBoxListInt32(ddlExamDateID);
            this.ExamDateID = intExamDateID;
            this.TemplateCode = "5";

            if (Request.Url.DnsSafeHost == "localhost" && Request["templatecode"] != null)
                this.TemplateCode = Request["templatecode"].ToString();

            SimsObject.SIM_Student obj = new SimsObject.SIM_Student();
            this.dtbData = obj.GetDataTable("WEB_StudentInfoList_HD_Mau5ThanhLy",
                "@ExamDateID", intExamDateID);

            if (dtbData != null)
                BindDataGrid();
            else
                MsgBox.ShowError("Việc tải thông tin bị lỗi!");
        }

        private void LoadData()
        {
            if (chkThanLy.Checked)
            {
                LoadDataMau5ThanhLy();
                return;
            }

            this.ExamDateID = null;

            bool? bolDinhChi = null;
            if (rdoStatus1.Checked)
                bolDinhChi = false;
            else if (rdoStatus2.Checked)
                bolDinhChi = true;

            SimsObject.SIM_Student obj = new SimsObject.SIM_Student();
            this.dtbData = obj.GetDataTable("WEB_StudentInfoList_HD",
                                        "@ClassID", uClass.ClassID,
                                        "@CourseID", uClass.CourseID,
                                        "@ScienceID", uClass.ScienceID,
                                        "@DinhChi", bolDinhChi);

            if (dtbData != null)
                BindDataGrid();
            else
                MsgBox.ShowError("Việc tải thông tin bị lỗi!");
        }

        private bool IsValidData(bool isShowMsg = true)
        {
            if (chkThanLy.Checked)
            {
                if (ddlExamDateID.SelectedIndex <= 0)
                {
                    if (isShowMsg)
                        MsgBox.ShowWarning("Bạn phải chọn kỳ thi!");
                    return false;
                }

                return true;
            }

            if (uClass.ClassID == null)
            {
                if (isShowMsg)
                    MsgBox.ShowWarning("Bạn phải chọn lớp học!");

                return false;
            }

            return true;
        }

